import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/f_geometria-del-piano-euclideo/fj/fj.md","filePath":"lezioni/f_geometria-del-piano-euclideo/fj/fj.md"}`),a={name:`lezioni/f_geometria-del-piano-euclideo/fj/fj.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h2 id="circonferenza-e-cerchio" tabindex="-1">Circonferenza e cerchio <a class="header-anchor" href="#circonferenza-e-cerchio" aria-label="Permalink to “Circonferenza e cerchio”">​</a></h2><p>Usiamo ora il luogo geometrico per definire un&#39;importantissima figura geometrica.</p><p>Definiamo <strong>circonferenza</strong> il luogo geometrico dei punti del piano equidistanti da un punto fisso detto centro.</p><p>Definiamo <strong>cerchio</strong> la parte finita di piano delimitata da una circonferenza.</p><blockquote><p><strong>Nota bene!</strong> La circonferenza è solo il bordo, cioè una linea, mentre il cerchio è la parte interna a tale linea.</p></blockquote><blockquote><p>Se nel cerchio comprendiamo anche la linea della circonferenza diremo che il cerchio è chiuso. Se nel cerchio non comprendiamo la circonferenza di bordo allora diremo che il cerchio è aperto. In mancanza di indicazioni indicheremo sempre il cerchio come chiuso.</p></blockquote><blockquote><p>Si potrebbe anche definire la circonferenza come figura geometrica: <strong>la circonferenza è il <a href="./../fg/fgba.html">poligono regolare</a> con un numero infinito di lati</strong>, però ci troveremmo ad affrontare l&#39;infinito...</p></blockquote><ul><li><a href="./fja.html">Convenzioni e definizioni</a></li><li><a href="./fjb.html">Proprietà delle corde</a></li><li><a href="./fjc.html">Mutue posizioni fra retta e circonferenza</a></li><li><a href="./fjd.html">Relazione fra archi e corde</a></li><li><a href="./fje.html">Mutue posizioni fra due circonferenze</a></li><li><a href="./fjf.html">Angoli al centro ed alla circonferenza</a></li></ul>`,8)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};